import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Phase 01 Image Threat Model","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/security/threat-model.md"},"headers":[],"relativePath":"sovereign-os/security/threat-model.md","filePath":"sovereign-os/security/threat-model.md"}'),o={name:"sovereign-os/security/threat-model.md"};function n(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="phase-01-image-threat-model" tabindex="-1">Phase 01 Image Threat Model <a class="header-anchor" href="#phase-01-image-threat-model" aria-label="Permalink to &quot;Phase 01 Image Threat Model&quot;">​</a></h1><p><strong>Status:</strong> Draft<br><strong>Version:</strong> 0.2<br><strong>Scope:</strong> Flashable Docker-based Pi-hole appliance image</p><h2 id="security-goals" tabindex="-1">Security Goals <a class="header-anchor" href="#security-goals" aria-label="Permalink to &quot;Security Goals&quot;">​</a></h2><ul><li>Publish an image free of build-machine identity and secrets.</li><li>Give every flashed device unique identity and application credentials, and limit the accepted preview bootstrap exception.</li><li>Expose only the network services required for DNS and local administration.</li><li>Prevent Pi-hole from occupying future Sovereign <code>/admin</code> and <code>/api</code> namespaces.</li><li>Keep Pi-hole data and credentials on user-owned storage.</li><li>Make interrupted initialization recoverable.</li><li>Make release inputs and artifacts verifiable.</li></ul><h2 id="protected-assets" tabindex="-1">Protected Assets <a class="header-anchor" href="#protected-assets" aria-label="Permalink to &quot;Protected Assets&quot;">​</a></h2><ul><li>Raspberry Pi host and boot integrity</li><li>Pi-hole administrator credential</li><li>Pi-hole configuration, query data, client identities, and statistics</li><li>Docker daemon and host filesystem</li><li>Persistent application data</li><li>Image build and release integrity</li><li>Future Sovereign route namespaces</li></ul><h2 id="actors-and-boundaries" tabindex="-1">Actors and Boundaries <a class="header-anchor" href="#actors-and-boundaries" aria-label="Permalink to &quot;Actors and Boundaries&quot;">​</a></h2><ul><li>Authorized household administrator</li><li>Other devices and users on the local network</li><li>Internet hosts contacted for upstream DNS and later updates</li><li>Base-OS and package repositories</li><li>Container registry and Pi-hole release publishers</li><li>Compromised dependency or build environment</li><li>Physical holder of the Raspberry Pi or storage device</li></ul><p>The local network reduces exposure but is not fully trusted. Physical compromise and hostile public internet exposure are outside Phase 01 protection claims.</p><h2 id="threats-and-controls" tabindex="-1">Threats and Controls <a class="header-anchor" href="#threats-and-controls" aria-label="Permalink to &quot;Threats and Controls&quot;">​</a></h2><h3 id="t-01-shared-or-leaked-image-credentials" tabindex="-1">T-01: Shared or Leaked Image Credentials <a class="header-anchor" href="#t-01-shared-or-leaked-image-credentials" aria-label="Permalink to &quot;T-01: Shared or Leaked Image Credentials&quot;">​</a></h3><p><strong>Threat:</strong> Every flashed device inherits the same password, SSH keys, machine ID, token, or build-host secret.<br><strong>Controls:</strong> Generate identity and Pi-hole credentials on first boot; sanitize the final filesystem; scan the exported image; prohibit application credentials in build configuration and Compose YAML. ADR-0003 permits a public, expired bootstrap password only in preview images, requires immediate replacement, and prohibits public-network exposure. <strong>Verification:</strong> Mount and scan the exact compressed release artifact after decompression; verify that SSH forces replacement before granting a shell and rejects the initial password afterward.</p><h3 id="t-02-malicious-or-mutable-build-input" tabindex="-1">T-02: Malicious or Mutable Build Input <a class="header-anchor" href="#t-02-malicious-or-mutable-build-input" aria-label="Permalink to &quot;T-02: Malicious or Mutable Build Input&quot;">​</a></h3><p><strong>Threat:</strong> A changed base image, package, script, or <code>latest</code> container silently alters a release.<br><strong>Controls:</strong> Pin source revisions and Pi-hole digest; record base-OS and package inputs; publish checksums and provenance; review dependency sources.<br><strong>Verification:</strong> Compare manifest inputs and verify the embedded OCI digest.</p><h3 id="t-03-docker-daemon-or-container-escape" tabindex="-1">T-03: Docker Daemon or Container Escape <a class="header-anchor" href="#t-03-docker-daemon-or-container-escape" aria-label="Permalink to &quot;T-03: Docker Daemon or Container Escape&quot;">​</a></h3><p><strong>Threat:</strong> Compromise of Pi-hole gains unnecessary host authority.<br><strong>Controls:</strong> No Docker socket mount; no privileged mode; no unnecessary capabilities; limited bind mounts; patched runtime; host directories with restrictive ownership.<br><strong>Verification:</strong> Inspect effective container configuration and mount/capability sets.</p><h3 id="t-04-unintended-network-exposure" tabindex="-1">T-04: Unintended Network Exposure <a class="header-anchor" href="#t-04-unintended-network-exposure" aria-label="Permalink to &quot;T-04: Unintended Network Exposure&quot;">​</a></h3><p><strong>Threat:</strong> Docker or host services publish administrative or internal ports beyond the intended LAN boundary.<br><strong>Controls:</strong> Document listener ownership; Pi-hole web backend bound to loopback; only DNS and Nginx intentionally exposed; firewall and socket inspection.<br><strong>Verification:</strong> Scan the target from another local device and inspect host/container listeners.</p><h3 id="t-05-unauthenticated-pi-hole-administration" tabindex="-1">T-05: Unauthenticated Pi-hole Administration <a class="header-anchor" href="#t-05-unauthenticated-pi-hole-administration" aria-label="Permalink to &quot;T-05: Unauthenticated Pi-hole Administration&quot;">​</a></h3><p><strong>Threat:</strong> Another local device obtains administrative access.<br><strong>Controls:</strong> Unique strong password; no empty password; secure password delivery; no password in logs or unauthenticated endpoints.<br><strong>Verification:</strong> Attempt access without credentials and inspect all delivery/log paths.</p><h3 id="t-06-route-prefix-escape" tabindex="-1">T-06: Route Prefix Escape <a class="header-anchor" href="#t-06-route-prefix-escape" aria-label="Permalink to &quot;T-06: Route Prefix Escape&quot;">​</a></h3><p><strong>Threat:</strong> Ambiguous paths, encoded traversal, or proxy behavior sends <code>/admin</code> or <code>/api</code> traffic to Pi-hole or escapes <code>/dns</code>.<br><strong>Controls:</strong> Explicit Nginx locations; normalized paths; Pi-hole prefix setting; reject ambiguous encodings; regression tests.<br><strong>Verification:</strong> Test normal, encoded, doubled-slash, and traversal-shaped requests.</p><h3 id="t-07-dns-service-abuse" tabindex="-1">T-07: DNS Service Abuse <a class="header-anchor" href="#t-07-dns-service-abuse" aria-label="Permalink to &quot;T-07: DNS Service Abuse&quot;">​</a></h3><p><strong>Threat:</strong> Pi-hole becomes an open resolver or answers on unintended interfaces.<br><strong>Controls:</strong> Local-network listening policy; no router port forwarding; documented firewall; verify IPv4 and IPv6 behavior.<br><strong>Verification:</strong> Inspect bindings and test from permitted and non-permitted network positions where available.</p><h3 id="t-08-sensitive-dns-data-disclosure" tabindex="-1">T-08: Sensitive DNS Data Disclosure <a class="header-anchor" href="#t-08-sensitive-dns-data-disclosure" aria-label="Permalink to &quot;T-08: Sensitive DNS Data Disclosure&quot;">​</a></h3><p><strong>Threat:</strong> Query history or client identity appears in host logs, support artifacts, or unintended routes.<br><strong>Controls:</strong> Pi-hole data stays in its persistent directory; minimize proxy logs; document query logging/privacy defaults; inspect diagnostic output.<br><strong>Verification:</strong> Generate identifiable test queries and search normal logs and release artifacts.</p><h3 id="t-09-first-boot-corruption" tabindex="-1">T-09: First-Boot Corruption <a class="header-anchor" href="#t-09-first-boot-corruption" aria-label="Permalink to &quot;T-09: First-Boot Corruption&quot;">​</a></h3><p><strong>Threat:</strong> Power loss leaves partial secrets, imported images, invalid configuration, or a false completion state.<br><strong>Controls:</strong> Idempotent steps; atomic writes; restrictive permissions before content; health-gated completion; recoverable embedded artifact.<br><strong>Verification:</strong> Interrupt power or service execution at defined steps and resume.</p><h3 id="t-10-dhcp-disruption" tabindex="-1">T-10: DHCP Disruption <a class="header-anchor" href="#t-10-dhcp-disruption" aria-label="Permalink to &quot;T-10: DHCP Disruption&quot;">​</a></h3><p><strong>Threat:</strong> Pi-hole DHCP competes with the router and disrupts the household network.<br><strong>Controls:</strong> DHCP disabled; port 67 unpublished; no <code>NET_ADMIN</code> solely for DHCP.<br><strong>Verification:</strong> Inspect Pi-hole configuration, Compose ports, and effective capabilities.</p><h3 id="t-11-unsafe-update-or-rollback" tabindex="-1">T-11: Unsafe Update or Rollback <a class="header-anchor" href="#t-11-unsafe-update-or-rollback" aria-label="Permalink to &quot;T-11: Unsafe Update or Rollback&quot;">​</a></h3><p><strong>Threat:</strong> Incompatible Pi-hole or container changes corrupt persistent data.<br><strong>Controls:</strong> No unattended <code>latest</code> pulls; explicit pinned releases; backup and migration testing before update; compatibility notes.<br><strong>Verification:</strong> Test updates on copied data before publishing an update path.</p><h2 id="required-security-tests-before-release" tabindex="-1">Required Security Tests Before Release <a class="header-anchor" href="#required-security-tests-before-release" aria-label="Permalink to &quot;Required Security Tests Before Release&quot;">​</a></h2><ul><li>Final image identity and secret scan</li><li>SBOM or documented Phase 01 deferral</li><li>Container digest verification</li><li>Container privilege, mount, and capability inspection</li><li>Host and remote port scans</li><li><code>/dns/*</code> path-boundary regression tests</li><li>Authentication and password reset tests</li><li>First-boot interruption tests</li><li>IPv4 and IPv6 exposure review</li><li>Log and diagnostic data review</li></ul><h2 id="known-phase-01-limitations" tabindex="-1">Known Phase 01 Limitations <a class="header-anchor" href="#known-phase-01-limitations" aria-label="Permalink to &quot;Known Phase 01 Limitations&quot;">​</a></h2><ul><li>HTTP is not confidential on the local network.</li><li>mDNS is discovery, not authentication.</li><li>The image is not designed for public internet exposure.</li><li>Anyone with physical storage access may read unencrypted Pi-hole data and secrets.</li><li>Automatic security update and rollback infrastructure is not yet implemented.</li><li>Router security and configuration remain outside the image&#39;s control.</li></ul>',36)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
